def dense(p,step=1.):
 t=np.r_[0,np.cumsum(np.linalg.norm(np.diff(p[:,:2],axis=0),axis=1))]
 t=np.maximum.accumulate(t+np.arange(len(t))*1e-5)
 tt=np.linspace(0,t[-1],max(3,int(t[-1]/step)+1))
 # Smooth geometry, with bounded local interpolation for the pressure profile.
 xy=CubicSpline(t,p[:,:2],bc_type='natural')(tt)
