 return np.c_[xy,ww,np.arctan2(der[:,1],der[:,0])]

def render(p,box=(0,0,1024,1024),step=1.):
 x0,y0,x1,y1=box
 a=np.zeros((y1-y0,x1-x0),np.float32)
 pts=np.ascontiguousarray(dense(p,step),np.float64)
 lib.render(a.ctypes.data,*a.shape,x0,y0,pts.ctypes.data,len(pts))
 return a

def report(P,name):
