 cv2.imwrite(DIR+name+'.png',img)
 cv2.imwrite(DIR+name+'_ink.png',np.uint8(255*(1-A)))
 return A

def optimize(P,cycles=1,maxiter=12):
 A=[render(p) for p in P]
 for cycle in range(cycles):
